<script setup lang="ts">
import {computed,onMounted} from 'vue';import {Crosshair,LayoutDashboard,ChartNoAxesCombined,Medal,CalendarDays,MessagesSquare,Settings,RefreshCw,ShieldCheck,ArrowUpRight} from 'lucide-vue-next';
import {useAppStore,time} from './store';import Dashboard from './pages/Dashboard.vue';import Scenarios from './pages/Scenarios.vue';import Benchmarks from './pages/Benchmarks.vue';import TrainingPlan from './pages/TrainingPlan.vue';import Coach from './pages/Coach.vue';import SettingsPage from './pages/Settings.vue';
const app=useAppStore();const nav=[{id:'dashboard',label:'训练概览',en:'Dashboard',icon:LayoutDashboard},{id:'scenarios',label:'场景与成长',en:'Scenarios',icon:ChartNoAxesCombined},{id:'benchmarks',label:'能力基准',en:'Benchmarks',icon:Medal},{id:'plan',label:'今天练什么',en:'Training plan',icon:CalendarDays},{id:'coach',label:'智能教练',en:'AI Coach',icon:MessagesSquare},{id:'settings',label:'设置',en:'Settings',icon:Settings}];const current=computed(()=>nav.find(n=>n.id===app.page)!);onMounted(()=>app.init());
